describe('Billing Address Change During Checkout', () => {
  beforeEach(() => {
    cy.visit('/checkout');
  });

  it('should successfully update billing address during checkout', () => {
    // Navigate to checkout page
    cy.get('[data-testid="checkout-button"]').click();

    // Verify initial billing address is displayed
    cy.get('[data-testid="billing-address-input"]').should('be.visible');
    cy.get('[data-testid="billing-address-input"]').should('contain', '123 Main St');

    // Fill in new billing address
    cy.get('[data-testid="billing-address-input"]').type('456 Elm St');
    cy.get('[data-testid="billing-address-input"]').type('Apt 101');
    cy.get('[data-testid="billing-address-input"]').type('New York');
    cy.get('[data-testid="billing-city-input"]').type('New York');
    cy.get('[data-testid="billing-state-input"]').type('NY');
    cy.get('[data-testid="billing-zip-input"]').type('10001');

    // Verify address fields are updated
    cy.get('[data-testid="billing-address-input"]').should('contain', '456 Elm St');
    cy.get('[data-testid="billing-city-input"]').should('contain', 'New York');
    cy.get('[data-testid="billing-state-input"]').should('contain', 'NY');

    // Verify address validation is passed
    cy.get('[data-testid="billing-address-validation-message"]').should('not.exist');

    // Proceed to checkout
    cy.get('[data-testid="continue-button"]').click();

    // Verify success message appears
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Billing address updated successfully');

    // Verify order summary reflects new address
    cy.get('[data-testid="order-summary"]').should('be.visible');
    cy.get('[data-testid="order-summary"]').should('contain', 'New billing address');

    // Verify order can be completed
    cy.get('[data-testid="complete-order-button"]').click();

    // Verify order confirmation page is displayed
    cy.get('[data-testid="order-confirmation-page"]').should('be.visible');
  });

  it('should display error when billing address is invalid', () => {
    // Navigate to checkout page
    cy.get('[data-testid="checkout-button"]').click();

    // Fill in invalid billing address
    cy.get('[data-testid="billing-address-input"]').type('1234567890');
    cy.get('[data-testid="billing-address-input"]').type('Apt 101');
    cy.get('[data-testid="billing-city-input"]').type('Invalid City');
    cy.get('[data-testid="billing-state-input"]').type('NY');
    cy.get('[data-testid="billing-zip-input"]').type('10001');

    // Verify error message appears
    cy.get('[data-testid="billing-address-error-message"]').should('be.visible');
    cy.get('[data-testid="billing-address-error-message"]').should('contain', 'Please enter a valid address');

    // Verify address fields are not updated
    cy.get('[data-testid="billing-address-input"]').should('contain', '1234567890');

    // Verify validation error persists
    cy.get('[data-testid="billing-address-validation-message"]').should('be.visible');

    // Attempt to proceed with invalid address
    cy.get('[data-testid="continue-button"]').click();

    // Verify error message is still visible
    cy.get('[data-testid="billing-address-error-message"]').should('be.visible');

    // Verify order cannot be completed
    cy.get('[data-testid="complete-order-button"]').should('be.disabled');
  });
});
